SELECT user_id
FROM chat_conversation_member
WHERE conversation_id = #{conversationId}
  AND user_id != #{excludeUserId}
  AND leave_time IS NULL

SELECT COUNT(1)
FROM chat_conversation_member
WHERE conversation_id = #{conversationId}
  AND user_id = #{userId}
  AND leave_time IS NULL

SELECT user_id
FROM chat_conversation_member
WHERE conversation_id = #{conversationId}
  AND user_id != #{senderId}
  AND leave_time IS NULL
LIMIT 1

mapper.update:
UPDATE chat_conversation_member
SET unread_count = unread_count + 1
WHERE conversation_id = #{conversationId}
  AND user_id = #{userId}
  AND leave_time IS NULL

UPDATE chat_conversation_member
SET last_read_msg_id = #{msgId},
unread_count = 0,
join_time = join_time  
WHERE conversation_id = #{conversationId}
AND user_id = #{userId}

UPDATE chat_conversation_member
SET unread_count = 0
WHERE conversation_id = #{conversationId}
  AND user_id = #{userId}
